<script setup lang="ts">
import NetworkFields from './NetworkFields.vue'
import {ref,computed,watch} from 'vue'
type Row=Record<string,any>
const props=defineProps<{api:(p:string,m?:string,b?:any)=>Promise<any>,hosts:Row[],templates:Row[],certificates:Row[],initialHost?:string,initialEngine?:string}>(),emit=defineEmits(['close','saved'])
const host=ref(props.initialHost||props.hosts.find(h=>h.online)?.id||props.hosts[0]?.id||''),engine=ref(props.initialEngine||'sing-box'),selected=ref<string[]>(['vless']),name=ref(''),address=ref(props.hosts.find(h=>h.id===host.value)?.address||''),listen=ref('0.0.0.0'),start=ref(20000),certificate=ref(''),sni=ref('www.microsoft.com'),enabled=ref(false),busy=ref(false),error=ref(''),advanced=ref<Record<string,string>>({}),ports=ref<Record<string,number>>({})
const endpoints=ref<string[]>([]),egress=ref<string[]>([])
const requestKey=crypto.randomUUID().replaceAll('-',''),compatible=computed(()=>props.templates.filter(t=>t.engines?.includes(engine.value)&&!['frps','frpc'].includes(t.kind))),needsCert=computed(()=>selected.value.some(k=>['trojan','hysteria2','tuic','anytls'].includes(k)))
watch(engine,()=>{selected.value=selected.value.filter(k=>compatible.value.some(t=>t.kind===k))})
watch(host,id=>{address.value=props.hosts.find(h=>h.id===id)?.address||'';endpoints.value=[];egress.value=[]})
function all(){selected.value=selected.value.length===compatible.value.length?[]:compatible.value.map(t=>t.kind)}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{
 if(!selected.value.length)throw new Error('至少选择一个协议')
 const cert=props.certificates.find(c=>c.id===certificate.value)
 const items=selected.value.map(kind=>{const extra=JSON.parse(advanced.value[kind]||'{}');if(!extra||Array.isArray(extra)||typeof extra!=='object')throw new Error(kind+' 高级配置需要 JSON 对象');for(const key of ['name','host_id','engine','kind','node_id'])if(key in extra)throw new Error('高级配置不可覆盖 '+key)
  const row:Row={name:(name.value.trim()||props.hosts.find(h=>h.id===host.value)?.name||'VPS')+' · '+kind,host_id:host.value,engine:engine.value,kind,endpoint_addresses:endpoints.value,egress_families:egress.value,address:address.value,listen:listen.value,port:ports.value[kind]||0,managed_users:!['shadowsocks','snell'].includes(kind)}
  if(kind==='vless')Object.assign(row,{transport:'tcp',tls_mode:'reality',server_name:sni.value,flow:'xtls-rprx-vision',reality:{target:sni.value,port:443,fingerprint:'chrome'}})
  if(kind==='vmess')Object.assign(row,{transport:'tcp',tls_mode:'none'})
  if(['trojan','hysteria2','tuic','anytls'].includes(kind))Object.assign(row,{tls_mode:'tls',certificate_id:certificate.value,server_name:cert?.domain||''})
  return Object.assign(row,extra)
 });await props.api('live/batch','POST',{items,start_port:start.value,enabled:enabled.value,request_key:requestKey});emit('saved')
 }catch(e){error.value=String(e)}finally{busy.value=false}}
</script>
<template><div class="modal-backdrop" @keydown.esc="!busy&&emit('close')"><form class="modal topology-editor" role="dialog" aria-modal="true" aria-label="批量配置协议" @submit.prevent="save"><div class="modal-heading"><div><span class="eyebrow">HOST → KERNEL → PROTOCOLS</span><h2>一次配置多个协议</h2></div><button type="button" class="secondary" :disabled="busy" @click="emit('close')">关闭</button></div><div class="form-content"><p v-if="error" class="error" role="alert">{{error}}</p><div class="fields"><label>运行主机<select v-model="host" required><option v-for="h in hosts" :key="h.id" :value="h.id">{{h.name}}</option></select></label><label>内核<select v-model="engine"><option>sing-box</option><option>xray</option></select></label><label>名称前缀<input v-model="name" placeholder="默认使用主机名" maxlength="60"></label><label>客户端连接地址<input v-model="address" required placeholder="域名 / IPv4 / IPv6"></label><label>监听地址<input v-model="listen" required></label><label>自动分配起始端口<input v-model.number="start" type="number" min="1024" max="65535" required></label></div><NetworkFields :host="hosts.find(h=>h.id===host)" :endpoints="endpoints" :egress="egress" @endpoints="v=>{endpoints=v;if(v.length){address=v[0];if(v.some(x=>x.includes(':')))listen='::'}}" @egress="v=>egress=v"/><div class="section-heading"><h3>选择协议 · {{selected.length}} / {{compatible.length}}</h3><button class="secondary" type="button" @click="all">{{selected.length===compatible.length?'取消全选':'全选兼容协议'}}</button></div><div class="choice-list"><label v-for="t in compatible" :key="t.kind"><input v-model="selected" type="checkbox" :value="t.kind">{{t.name||t.kind}} <small>{{t.kind}}</small></label></div><p class="muted">全选范围随内核变化。VLESS 默认 REALITY，VMess 默认无 TLS；TLS 协议使用下方域名证书。端口冲突或任一协议无效时整批不保存。</p><div class="fields"><label v-if="selected.includes('vless')">REALITY 目标 / SNI<select v-model="sni"><option>www.microsoft.com</option><option>www.apple.com</option><option>www.cloudflare.com</option></select></label><label v-if="needsCert">TLS 协议共用证书<select v-model="certificate" required><option value="">选择已就绪证书</option><option v-for="c in certificates.filter(c=>c.state==='ready')" :key="c.id" :value="c.id">{{c.domain}}</option></select></label></div><p v-if="selected.includes('vless')" class="form-note">大厂域名只用于 REALITY 握手候选，需从此 VPS 可达且支持所需 TLS 握手；普通 TLS 的 SNI 必须匹配自己的证书。</p><details v-for="kind in selected" :key="kind"><summary>{{kind}} · 端口与高级参数</summary><label>监听端口（0 自动）<input v-model.number="ports[kind]" type="number" min="0" max="65535" placeholder="0"></label><label>协议参数 JSON 覆盖<textarea v-model="advanced[kind]" class="code-editor" rows="5" placeholder='{"transport":"ws","path":"/proxy"}' spellcheck="false"></textarea></label></details><label class="check-label"><input v-model="enabled" type="checkbox">保存后启用整批协议</label><p class="muted">默认保存为停用。启用时 Agent 会先检查该 VPS 的完整内核配置，成功后应用；只保存配置不代表公网端口已放行。SS / Snell 使用共享密钥订阅。</p></div><div class="modal-footer"><button type="button" class="secondary" :disabled="busy" @click="emit('close')">取消</button><button class="primary" :disabled="busy||!selected.length">{{busy?'正在校验并保存…':'保存 '+selected.length+' 个协议'}}</button></div></form></div></template>
<style scoped>.topology-editor{width:min(1000px,96vw)}.code-editor{font-family:Consolas,monospace;min-height:110px}details{padding:12px 0;border-bottom:1px solid var(--border)}h3{margin:0}.choice-list label{min-height:46px}</style>
